# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <math.h>

// Each block handles one (n, h, w) spatial position.
// Threads within the block cooperate to:
//   1. Compute GroupNorm mean/var for each group (iterating over all spatial positions in that group).
//   2. Apply affine, tanh, hardswish, residual add.
//   3. Compute numerically stable logsumexp over all C channels.
//
// NOTE: GroupNorm normalizes over (C/G channels) * (H*W) elements per (n, g) pair.
// The mean/var must be computed over the full spatial extent, not just one (h,w) position.
// We therefore need a two-pass approach per group.
//
// Strategy: assign one block per (n, g) pair. Each block computes mean/var for that group
// over all H*W*Cg elements, then writes the normalized+activated+residual values into
// shared memory, and finally reduces over all C channels (all groups) for logsumexp.
// But logsumexp needs all channels, spanning all groups, for one specific (n, h, w).
//
// Better: assign one block per (n, h, w). Each thread handles one or more channels.
// For GroupNorm, we need mean/var per (n, g) which spans H*W positions -- so we must
// do a global reduction over H*W for each group before we can normalize.
//
// We use a two-kernel approach:
//   Kernel 1: compute mean and variance for each (n, g) pair, output shape [N, G].
//   Kernel 2: for each (n, h, w), use precomputed stats to normalize, activate, residual-add,
//             then reduce logsumexp over C channels.

__global__ void groupnorm_stats_kernel(
    const float* __restrict__ x,  // [N, C, H, W]
    float* __restrict__ mean_out,  // [N, G]
    float* __restrict__ var_out,   // [N, G]
    int N, int C, int H, int W, int G
) {
    // blockIdx.x = n * G + g
    int ng = blockIdx.x;
    int n = ng / G;
    int g = ng % G;
    int Cg = C / G;  // channels per group
    int spatial = H * W;
    int total = Cg * spatial;  // elements per (n, g)

    // Channel range for this group
    int c_start = g * Cg;

    // Each thread accumulates sum and sum-of-squares over a strided portion
    float sum = 0.0f;
    float sum_sq = 0.0f;

    for (int i = threadIdx.x; i < total; i += blockDim.x) {
        int c_local = i / spatial;
        int hw = i % spatial;
        int c = c_start + c_local;
        float val = x[((n * C + c) * H + hw / W) * W + hw % W];
        sum += val;
        sum_sq += val * val;
    }

    // Block reduction using shared memory
    extern __shared__ float smem[];
    float* s_sum = smem;
    float* s_sq = smem + blockDim.x;

    s_sum[threadIdx.x] = sum;
    s_sq[threadIdx.x] = sum_sq;
    __syncthreads();

    for (int stride = blockDim.x / 2; stride > 0; stride >>= 1) {
        if (threadIdx.x < stride) {
            s_sum[threadIdx.x] += s_sum[threadIdx.x + stride];
            s_sq[threadIdx.x] += s_sq[threadIdx.x + stride];
        }
        __syncthreads();
    }

    if (threadIdx.x == 0) {
        float mean = s_sum[0] / total;
        float var = s_sq[0] / total - mean * mean;
        mean_out[ng] = mean;
        var_out[ng] = var;
    }
}

__global__ void fused_norm_act_logsumexp_kernel(
    const float* __restrict__ x_conv,   // [N, C, H, W]
    const float* __restrict__ mean_ng,  // [N, G]
    const float* __restrict__ var_ng,   // [N, G]
    const float* __restrict__ gn_weight, // [C]
    const float* __restrict__ gn_bias,   // [C]
    float* __restrict__ out,             // [N, 1, H, W]
    int N, int C, int H, int W, int G,
    float eps
) {
    // blockIdx.x = n * H * W + h * W + w
    int nhw = blockIdx.x;
    int n = nhw / (H * W);
    int hw = nhw % (H * W);
    int h = hw / W;
    int w = hw % W;

    int Cg = C / G;
    int spatial = H * W;

    // Two-pass logsumexp over C channels:
    // Pass 1: find max of (x_conv[n,c,h,w] + hardswish(tanh(norm(x_conv[n,c,h,w]))))
    // Pass 2: sum exp(val - max), then write log(sum) + max

    // Each thread handles C/blockDim.x channels (or we use all threads for reduction)
    // We'll have blockDim.x threads and each thread processes one or more channels

    // First compute all activated residual values (stored in registers / shared mem)
    // then do stable logsumexp reduction

    extern __shared__ float smem[];
    // smem layout: [0..C-1] = activated values, [C..C+blockDim-1] = reduction scratch

    // Phase 1: each thread computes its channels
    for (int c = threadIdx.x; c < C; c += blockDim.x) {
        int g = c / Cg;
        float mean = mean_ng[n * G + g];
        float var = var_ng[n * G + g];
        float inv_std = rsqrtf(var + eps);

        float xval = x_conv[((n * C + c) * H + h) * W + w];
        float x_norm = (xval - mean) * inv_std;
        float x_affine = x_norm * gn_weight[c] + gn_bias[c];

        // Tanh
        float x_tanh = tanhf(x_affine);

        // HardSwish: x * clamp(x+3, 0, 6) / 6
        float hs_inner = x_tanh + 3.0f;
        hs_inner = hs_inner < 0.0f ? 0.0f : (hs_inner > 6.0f ? 6.0f : hs_inner);
        float x_hardswish = x_tanh * hs_inner / 6.0f;

        // Residual add
        float x_res = xval + x_hardswish;

        smem[c] = x_res;
    }
    __syncthreads();

    // Phase 2: find max over all C channels
    float local_max = -1e38f;
    for (int c = threadIdx.x; c < C; c += blockDim.x) {
        float v = smem[c];
        if (v > local_max) local_max = v;
    }

    // Reduce max across threads
    float* s_max = smem + C;
    s_max[threadIdx.x] = local_max;
    __syncthreads();
    for (int stride = blockDim.x / 2; stride > 0; stride >>= 1) {
        if (threadIdx.x < stride) {
            if (s_max[threadIdx.x + stride] > s_max[threadIdx.x])
                s_max[threadIdx.x] = s_max[threadIdx.x + stride];
        }
        __syncthreads();
    }
    float global_max = s_max[0];
    __syncthreads();

    // Phase 3: sum exp(val - max)
    float local_sum = 0.0f;
    for (int c = threadIdx.x; c < C; c += blockDim.x) {
        local_sum += expf(smem[c] - global_max);
    }

    // Reduce sum across threads (reuse s_max buffer)
    s_max[threadIdx.x] = local_sum;
    __syncthreads();
    for (int stride = blockDim.x / 2; stride > 0; stride >>= 1) {
        if (threadIdx.x < stride) {
            s_max[threadIdx.x] += s_max[threadIdx.x + stride];
        }
        __syncthreads();
    }

    if (threadIdx.x == 0) {
        out[nhw] = logf(s_max[0]) + global_max;  // n*1*H*W + 0*H*W + h*W + w = nhw
    }
}

torch::Tensor conv_groupnorm_tanh_hardswish_residualadd_logsumexp_cuda(
    torch::Tensor x_conv,
    torch::Tensor gn_weight,
    torch::Tensor gn_bias,
    int64_t groups,
    double eps
) {
    TORCH_CHECK(x_conv.is_cuda(), "x_conv must be a CUDA tensor");
    TORCH_CHECK(x_conv.is_contiguous(), "x_conv must be contiguous");
    TORCH_CHECK(x_conv.scalar_type() == torch::kFloat32, "x_conv must be float32");
    TORCH_CHECK(gn_weight.is_contiguous() && gn_bias.is_contiguous(), "gn params must be contiguous");

    int N = x_conv.size(0);
    int C = x_conv.size(1);
    int H = x_conv.size(2);
    int W = x_conv.size(3);
    int G = (int)groups;

    TORCH_CHECK(C % G == 0, "C must be divisible by groups");
    TORCH_CHECK(gn_weight.size(0) == C && gn_bias.size(0) == C, "gn_weight/bias size mismatch");

    auto opts = x_conv.options();
    auto mean_ng = torch::empty({N * G}, opts);
    auto var_ng = torch::empty({N * G}, opts);
    auto output = torch::empty({N, 1, H, W}, opts);

    cudaStream_t stream = at::cuda::getCurrentCUDAStream();

    // Kernel 1: GroupNorm statistics
    int stats_threads = 256;
    int stats_blocks = N * G;
    size_t smem_stats = 2 * stats_threads * sizeof(float);
    groupnorm_stats_kernel<<<stats_blocks, stats_threads, smem_stats, stream>>>(
        x_conv.data_ptr<float>(),
        mean_ng.data_ptr<float>(),
        var_ng.data_ptr<float>(),
        N, C, H, W, G
    );

    // Kernel 2: fused normalize + activate + residual + logsumexp
    // Use power-of-2 block size >= C for efficient reduction
    int act_threads = 1;
    while (act_threads < C) act_threads <<= 1;
    if (act_threads > 1024) act_threads = 1024;
    // Ensure at least C threads aren't needed, but we handle C > blockDim via loop
    // Use min(C rounded up to power of 2, 256) for good occupancy
    act_threads = min(act_threads, 256);
    // Make sure act_threads is power of 2 for reduction
    // If C=64, act_threads=64; if C=128, act_threads=128; cap at 256

    int act_blocks = N * H * W;
    // smem: C floats for values + act_threads floats for reduction
    size_t smem_act = (C + act_threads) * sizeof(float);
    fused_norm_act_logsumexp_kernel<<<act_blocks, act_threads, smem_act, stream>>>(
        x_conv.data_ptr<float>(),
        mean_ng.data_ptr<float>(),
        var_ng.data_ptr<float>(),
        gn_weight.data_ptr<float>(),
        gn_bias.data_ptr<float>(),
        output.data_ptr<float>(),
        N, C, H, W, G,
        (float)eps
    );

    return output;
}
# <<<END_IMPROVE>>>
"""

